//! Parts generated by `kicad_part!` from symbols with `Sim.Device IBIS` (or the `ibis` block), in
//! the test libraries of `crates/kicad_lib/tests/fixtures`: they simulate the drivers and
//! receivers of `spice::ibis` on their own pins.

mod common;

use common::deck_of;
use cuprite_wire::{
    circuit::CircuitBuilder,
    ibis::Corner,
    kicad_part,
    naming::NetLabel,
    parts::Part,
    spice::{
        Ngspice, SpicePartInfo,
        digital::{DigitalSequence, Level},
        ibis::{
            IbisBuffer, IbisDiffBuffer, IbisDiffDriver, IbisDiffReceiver, IbisDriver, IbisReceiver,
            read_file,
        },
    },
};

kicad_part! {
    /// A rectangular driver, with corners per parameter.
    struct Tx {
        symbol: "test:IBIS_TX",
        footprint: none,
        symbol_dir: "crates/kicad_lib/tests/fixtures/symbols",
        sim_library_dir: "crates/kicad_lib/tests/fixtures",
    }
}

kicad_part! {
    /// A receiver with its pins in another order and a pin left out.
    struct Rx {
        symbol: "test:IBIS_RX",
        footprint: none,
        symbol_dir: "crates/kicad_lib/tests/fixtures/symbols",
        sim_library_dir: "crates/kicad_lib/tests/fixtures",
    }
}

kicad_part! {
    /// A differential driver named by its inverting pin.
    struct DiffTx {
        symbol: "test:IBIS_DIFF_TX",
        footprint: none,
        pins: { "2" => "p", "3" => "n", "1" => "gnd" },
        symbol_dir: "crates/kicad_lib/tests/fixtures/symbols",
        sim_library_dir: "crates/kicad_lib/tests/fixtures",
    }
}

kicad_part! {
    /// KiCad's IBIS driver symbol, given its model.
    struct LegacyTx {
        symbol: "test:IBIS_LEGACY",
        footprint: none,
        ibis: {
            library: "models/kicad_ibis.ibs",
            component: "Board",
            pin: "5",
            model: "out_3s",
            driver: true,
        },
        symbol_dir: "crates/kicad_lib/tests/fixtures/symbols",
        sim_library_dir: "crates/kicad_lib/tests/fixtures",
    }
}

kicad_part! {
    /// KiCad's differential IBIS symbol as a receiver.
    struct LegacyDiffRx {
        symbol: "test:IBIS_LEGACY_DIFF",
        footprint: none,
        ibis: { library: "models/kicad_ibis.ibs", pin: "3", diff: true },
        symbol_dir: "crates/kicad_lib/tests/fixtures/symbols",
        sim_library_dir: "crates/kicad_lib/tests/fixtures",
    }
}

kicad_part! {
    /// An output that cannot release the pin.
    struct PushPull {
        symbol: "test:IBIS_LEGACY",
        footprint: none,
        ibis: { library: "models/kicad_ibis.ibs", pin: "8", driver: true },
        symbol_dir: "crates/kicad_lib/tests/fixtures/symbols",
        sim_library_dir: "crates/kicad_lib/tests/fixtures",
    }
}

const PATH: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/crates/kicad_lib/tests/fixtures/models/kicad_ibis.ibs"
);

fn buffer(pin: &str, corner: Corner) -> IbisBuffer {
    IbisBuffer::of_pin(&read_file(PATH).unwrap(), "Board", pin, corner).unwrap()
}

/// The elements of the SPICE information.
fn elements(info: SpicePartInfo) -> (Vec<cuprite_wire::spice::SpiceElement>, Vec<String>) {
    match info {
        SpicePartInfo::Elements {
            elements,
            unused_pins,
        } => (elements, unused_pins),
        other => panic!("{other:?}"),
    }
}

#[test]
fn test_constants() {
    assert_eq!(
        std::path::Path::new(Tx::LIBRARY),
        std::path::Path::new(PATH)
    );
    assert_eq!((Tx::COMPONENT, Tx::IBIS_PIN), ("Board", "1"));
    assert_eq!(Rx::IBIS_PIN, "5");
    assert_eq!(Tx::PINS, ["1", "2"]);
    assert_eq!(DiffTx::PINS, ["gnd", "p", "n"]);
    // Read once.
    assert!(std::ptr::eq(Tx::file().unwrap(), Tx::file().unwrap()));
}

#[test]
fn test_driver() {
    let sequence = DigitalSequence::new(Level::Low).at(1e-9, Level::High);
    for corner in [Corner::Typ, Corner::Min, Corner::Max] {
        let tx = Tx::new(corner, sequence.clone()).unwrap();
        assert_eq!(tx.buffer(), &buffer("1", corner));
        assert_eq!(tx.sequence(), &sequence);
        // The driver of `spice::ibis` with its pins `out` and `gnd` on the symbol's 2 and 1.
        let driver = IbisDriver::new(buffer("1", corner), sequence.clone());
        let (mut expected, _) = elements(driver.spice().unwrap());
        expected[0].nodes = vec!["2".into(), "1".into()];
        let (got, unused) = elements(tx.spice().unwrap());
        assert_eq!(got, expected);
        assert!(unused.is_empty());
    }
    assert_eq!(tx_value(), "IBIS_TX");
}

fn tx_value() -> String {
    Tx::new(Corner::Typ, DigitalSequence::new(Level::Low))
        .unwrap()
        .value()
}

#[test]
fn test_kicad_sequence() {
    // `ton=10n toff=20n td=5n n=3`.
    let mut expected = DigitalSequence::new(Level::Low);
    for start in [5e-9, 35e-9, 65e-9] {
        expected.push(start, Level::High);
        expected.push(start + 10e-9, Level::Low);
    }
    let got = Tx::kicad_sequence();
    assert_eq!(got.initial(), Level::Low);
    assert_eq!(got.events().len(), expected.events().len());
    for ((t, l), (u, m)) in got.events().iter().zip(expected.events()) {
        assert!((t - u).abs() < 1e-18 && l == m, "{got:?}");
    }
    assert_eq!(DiffTx::kicad_sequence(), DigitalSequence::new(Level::Low));
}

#[test]
fn test_receiver() {
    let rx = Rx::new(Corner::Typ).unwrap();
    let file = read_file(PATH).unwrap();
    let input = IbisBuffer::of_pin_model(&file, "Board", "5", "in_cmos", Corner::Typ).unwrap();
    assert_eq!(rx.buffer(), &input);
    let (mut expected, _) = elements(IbisReceiver::new(input).spice().unwrap());
    // `Sim.Pins` `2=GND 1=IN/OUT`; pin 3 is not in the model.
    expected[0].nodes = vec!["1".into(), "2".into()];
    let (got, unused) = elements(rx.spice().unwrap());
    assert_eq!(got, expected);
    assert_eq!(unused, ["3"]);
}

#[test]
fn test_diff() {
    let file = read_file(PATH).unwrap();
    let pair = IbisDiffBuffer::of_pin(&file, "Board", "3", Corner::Typ).unwrap();
    let sequence = DigitalSequence::new(Level::High);
    let tx = DiffTx::new(Corner::Typ, sequence.clone()).unwrap();
    assert_eq!(tx.buffer(), &pair);
    let (mut expected, _) = elements(IbisDiffDriver::new(pair.clone(), sequence).spice().unwrap());
    expected[0].nodes = vec!["p".into(), "n".into(), "gnd".into()];
    assert_eq!(elements(tx.spice().unwrap()).0, expected);

    let rx = LegacyDiffRx::new(Corner::Max).unwrap();
    let pair = IbisDiffBuffer::of_pin(&file, "Board", "3", Corner::Max).unwrap();
    let (mut expected, _) = elements(IbisDiffReceiver::new(pair).spice().unwrap());
    // `Sim.Pins` `1=1 2=2 3=3`: GND, + and -.
    expected[0].nodes = vec!["2".into(), "3".into(), "1".into()];
    assert_eq!(elements(rx.spice().unwrap()).0, expected);
}

#[test]
fn test_ibis_block() {
    let tx = LegacyTx::new(Corner::Typ, DigitalSequence::new(Level::HiZ)).unwrap();
    assert_eq!(tx.buffer().model_name(), "out_3s");
    assert_eq!(LegacyTx::IBIS_PIN, "5");
    // The fields KiCad 10 has for the model.
    let fields = tx.kicad().unwrap().fields;
    let field = |name: &str| {
        fields
            .iter()
            .find(|(k, _)| k == name)
            .map(|(_, v)| v.as_str())
    };
    assert_eq!(field("Sim.Device"), Some("IBIS"));
    assert_eq!(field("Sim.Type"), Some("DCDRIVER"));
    assert_eq!(field("Sim.Name"), Some("Board"));
    assert_eq!(field("Sim.Ibis.Pin"), Some("5"));
    assert_eq!(field("Sim.Ibis.Model"), Some("out_3s"));
    assert_eq!(field("Sim.Ibis.Diff"), None);
    assert_eq!(field("Sim.Pins"), Some("1=GND 2=IN/OUT"));
    assert_eq!(
        field("Sim.Library").map(std::path::PathBuf::from),
        Some(std::path::PathBuf::from(PATH))
    );
    let rx = LegacyDiffRx::new(Corner::Typ).unwrap();
    let fields = rx.kicad().unwrap().fields;
    assert!(fields.contains(&("Sim.Type".into(), "DEVICE".into())));
    assert!(fields.contains(&("Sim.Ibis.Diff".into(), "1".into())));
    assert!(fields.contains(&("Sim.Pins".into(), "1=GND 2=+ 3=-".into())));
}

#[test]
#[should_panic(expected = "cannot drive")]
fn test_level_not_driven() {
    // `out_pp` (an Output) cannot release the pin.
    let _ = PushPull::new(Corner::Typ, DigitalSequence::new(Level::HiZ));
}

/// The driver plays its KiCad stimulus into the receiver through a symbol-pin netlist.
#[test]
fn test_simulate() {
    let mut circuit = CircuitBuilder::new();
    let tx = circuit.instantiate_part(Tx::new(Corner::Typ, Tx::kicad_sequence()).unwrap());
    let rx = circuit.instantiate_part(Rx::new(Corner::Typ).unwrap());
    circuit.connect(tx["2"], rx["1"]);
    circuit.label(tx["2"], NetLabel::local("LINE"));
    circuit.label(tx["1"], NetLabel::global("GND"));
    circuit.label(rx["2"], NetLabel::global("GND"));
    circuit.no_connect(rx["3"]);
    let line = r#"v("/LINE")"#;
    let deck = deck_of(&circuit).control(vec![
        "tran 10p 100n".to_string(),
        format!("wrdata line.txt {line}"),
    ]);
    let table = Ngspice::new("ngspice")
        .run(&deck)
        .unwrap_or_else(|e| panic!("{e}"))
        .table("line.txt")
        .unwrap();
    let read = Rx::new(Corner::Typ)
        .unwrap()
        .buffer()
        .input()
        .unwrap()
        .decode(table.scale(), table.column(line).unwrap());
    assert_eq!(read.initial(), Level::Low);
    let edges: Vec<(f64, Level)> = read.events().to_vec();
    assert_eq!(edges.len(), 6, "{read:?}");
    for (i, (t, level)) in edges.iter().enumerate() {
        let start = 5e-9 + (i / 2) as f64 * 30e-9 + if i % 2 == 1 { 10e-9 } else { 0.0 };
        let expected = if i % 2 == 0 { Level::High } else { Level::Low };
        assert_eq!(*level, expected);
        assert!(*t > start && *t < start + 2e-9, "{i}: {t}");
    }
}

/// KiCad's own IBIS symbols (feature `kicad-libraries`), which need the `ibis` block.
#[cfg(feature = "kicad-libraries")]
mod kicad_libraries {
    use super::*;

    kicad_part! {
        struct Driver {
            symbol: "Simulation_SPICE:IBIS_DRIVER",
            footprint: none,
            ibis: { library: "models/kicad_ibis.ibs", pin: "1", driver: true },
            sim_library_dir: "crates/kicad_lib/tests/fixtures",
        }
    }

    kicad_part! {
        struct DiffReceiver {
            symbol: "Simulation_SPICE:IBIS_DEVICE_DIFF",
            footprint: none,
            ibis: { library: "models/kicad_ibis.ibs", pin: "3", diff: true },
            sim_library_dir: "crates/kicad_lib/tests/fixtures",
        }
    }

    #[test]
    fn test_kicad_symbols() {
        let sequence = DigitalSequence::new(Level::Low);
        let driver = Driver::new(Corner::Typ, sequence.clone()).unwrap();
        let (mut expected, _) = elements(
            IbisDriver::new(buffer("1", Corner::Typ), sequence)
                .spice()
                .unwrap(),
        );
        // Pin 1 is the reference (`Sim.Pins` `1=1 2=2`: the model pins GND and IN/OUT).
        expected[0].nodes = vec!["2".into(), "1".into()];
        assert_eq!(elements(driver.spice().unwrap()).0, expected);

        let file = read_file(PATH).unwrap();
        let pair = IbisDiffBuffer::of_pin(&file, "Board", "3", Corner::Typ).unwrap();
        let (mut expected, _) = elements(IbisDiffReceiver::new(pair).spice().unwrap());
        expected[0].nodes = vec!["2".into(), "3".into(), "1".into()];
        let receiver = DiffReceiver::new(Corner::Typ).unwrap();
        assert_eq!(elements(receiver.spice().unwrap()).0, expected);
    }
}
